37	/**
38	 * The heterogeneous simple assignment builder is used to generate the target assignment for a share group with
39	 * at least one of its members subscribed to a different set of topics.
40	 * <p>
41	 * Assignments are done according to the following principles:
42	 * <ol>
43	 *   <li>Balance:          Ensure partitions are distributed equally among all members.
44	 *                         The difference in assignments sizes between any two members
45	 *                         should not exceed one partition.</li>
46	 *   <li>Stickiness:       Minimize partition movements among members by retaining
47	 *                         as much of the existing assignment as possible.</li>
48	 * </ol>
49	 * <p>
50	 * Balance is prioritized above stickiness.
51	 * <p>
52	 * Note that balance is computed for each topic individually and then the assignments are combined. So, if M1
53	 * is subscribed to T1, M2 is subscribed to T2, and M3 is subscribed to T1 and T2, M3 will get assigned half
54	 * of the partitions for T1 and half of the partitions for T2.
55	 */
56	public class SimpleHeterogeneousAssignmentBuilder {
57	
58	    /**
59	     * The list of all the topic Ids that the share group is subscribed to.
60	     */
61	    private final Set<Uuid> subscribedTopicIds;
62	
63	    /**
64	     * The list of members in the consumer group.
65	     */
66	    private final List<String> memberIds;
67	
68	    /**
69	     * Maps member ids to their indices in the memberIds list.
70	     */
71	    private final Map<String, Integer> memberIndices;
72	
73	    /**
74	     * Subscribed members by topic.
75	     */
76	    private final Map<Uuid, List<Integer>> subscribedMembersByTopic;
77	
78	    /**
79	     * The list of all the topic-partitions assignable for the share group, grouped by topic.
80	     */
81	    private final Map<Uuid, List<TopicIdPartition>> targetPartitionsByTopic;
82	
83	    /**
84	     * The number of members in the share group.
85	     */
86	    private final int numGroupMembers;
87	
88	    /**
89	     * The share group assignment from the group metadata specification at the start of the assignment operation.
90	     * <p>
91	     * Members are stored as integer indices into the memberIds array.
92	     */
93	    private final Map<Integer, Map<Uuid, Set<Integer>>> oldGroupAssignment;
94	
95	    /**
96	     * The share group assignment calculated iteratively by the assignment operation. Entries in this map override those
97	     * in the old group assignment map.
98	     * <p>
99	     * Members are stored as integer indices into the memberIds array.
100	     */
101	    private final Map<Integer, Map<Uuid, Set<Integer>>> newGroupAssignment;
102	
103	    public SimpleHeterogeneousAssignmentBuilder(GroupSpec groupSpec, SubscribedTopicDescriber subscribedTopicDescriber) {
104	        this.subscribedTopicIds = new HashSet<>();
105	        groupSpec.memberIds().forEach(memberId -> subscribedTopicIds.addAll(groupSpec.memberSubscription(memberId).subscribedTopicIds()));
106	
107	        // Number the members 0 to M - 1.
108	        this.numGroupMembers = groupSpec.memberIds().size();
109	        this.memberIds = new ArrayList<>(groupSpec.memberIds());
110	        this.memberIndices = Utils.newHashMap(numGroupMembers);
111	        for (int memberIndex = 0; memberIndex < numGroupMembers; memberIndex++) {
112	            memberIndices.put(memberIds.get(memberIndex), memberIndex);
113	        }
114	
115	        this.targetPartitionsByTopic = computeTargetPartitions(groupSpec, subscribedTopicIds, subscribedTopicDescriber);
116	        this.subscribedMembersByTopic = computeSubscribedMembers(groupSpec, subscribedTopicIds, memberIndices);
117	
118	        this.oldGroupAssignment = Utils.newHashMap(numGroupMembers);
119	        this.newGroupAssignment = Utils.newHashMap(numGroupMembers);
120	
121	        // Extract the old group assignment from the group metadata specification.
122	        groupSpec.memberIds().forEach(memberId -> {
123	            int memberIndex = memberIndices.get(memberId);
124	            oldGroupAssignment.put(memberIndex, groupSpec.memberAssignment(memberId).partitions());
125	        });
126	    }
127	
128	    /**
129	     * Here's the step-by-step breakdown of the assignment process, performed for each subscribed topic in turn:
130	     * <ol>
131	     *   <li>Revoke partitions from the existing assignment that are no longer part of each member's subscriptions.</li>
132	     *   <li>Revoke partitions from members which have too many partitions.</li>
133	     *   <li>Revoke any partitions which are shared more than desired.</li>
134	     *   <li>Assign any partitions which have insufficient members assigned.</li>
135	     * </ol>
136	     */
137	    public GroupAssignment build() {
138	        if (subscribedTopicIds.isEmpty()) {
139	            return new GroupAssignment(Map.of());
140	        }
141	
142	        // Compute the partition assignments for each topic separately.
143	        subscribedTopicIds.forEach(topicId -> {
144	            TopicAssignmentPartialBuilder topicAssignmentBuilder =
145	                new TopicAssignmentPartialBuilder(topicId, numGroupMembers, targetPartitionsByTopic.get(topicId), subscribedMembersByTopic.get(topicId));
146	            topicAssignmentBuilder.build();
147	        });
148	
149	        // Combine the old and the new group assignments to give the result.
150	        Map<String, MemberAssignment> targetAssignment = Utils.newHashMap(numGroupMembers);
151	        for (int memberIndex = 0; memberIndex < numGroupMembers; memberIndex++) {
152	            Map<Uuid, Set<Integer>> memberAssignment = newGroupAssignment.get(memberIndex);
153	            if (memberAssignment == null) {
154	                targetAssignment.put(memberIds.get(memberIndex), new MemberAssignmentImpl(oldGroupAssignment.get(memberIndex)));
155	            } else {
156	                targetAssignment.put(memberIds.get(memberIndex), new MemberAssignmentImpl(memberAssignment));
157	            }
158	        }
159	
160	        return new GroupAssignment(targetAssignment);
161	    }
162	
163	    /**
164	     * Computes the list of target partitions which can be assigned to members. This list includes all partitions
165	     * for the subscribed topic IDs, with the additional check that they must be assignable.
166	     * @param groupSpec                 The assignment spec which includes member metadata.
167	     * @param subscribedTopicIds        The set of subscribed topic IDs.
168	     * @param subscribedTopicDescriber  The topic and partition metadata describer.
169	     * @return The list of target partitions, grouped by topic.
170	     */
171	    private static Map<Uuid, List<TopicIdPartition>> computeTargetPartitions(
172	        GroupSpec groupSpec,
173	        Set<Uuid> subscribedTopicIds,
174	        SubscribedTopicDescriber subscribedTopicDescriber
175	    ) {
176	        Map<Uuid, List<TopicIdPartition>> targetPartitionsByTopic = Utils.newHashMap(subscribedTopicIds.size());
177	        subscribedTopicIds.forEach(topicId -> {
178	            int numPartitions = subscribedTopicDescriber.numPartitions(topicId);
179	            if (numPartitions == -1) {
180	                throw new PartitionAssignorException(
181	                    "Members are subscribed to topic " + topicId + " which doesn't exist in the topic metadata."
182	                );
183	            }
184	
185	            List<TopicIdPartition> targetPartitions = new ArrayList<>(numPartitions);
186	            for (int partition = 0; partition < numPartitions; partition++) {
187	                if (groupSpec.isPartitionAssignable(topicId, partition)) {
188	                    targetPartitions.add(new TopicIdPartition(topicId, partition));
189	                }
190	            }
191	            targetPartitionsByTopic.put(topicId, targetPartitions);
192	        });
193	
194	        return targetPartitionsByTopic;
195	    }
196	
197	    /**
198	     * Computes the list of member indices which are subscribed to each topic.
199	     * @param groupSpec                 The assignment spec which includes member metadata.
200	     * @param subscribedTopicIds        The set of subscribed topic IDs.
201	     * @param memberIndices             The map from member IDs to member indices.
202	     * @return The list of member indices, grouped by topic.
203	     */
204	    private static Map<Uuid, List<Integer>> computeSubscribedMembers(
205	        GroupSpec groupSpec,
206	        Set<Uuid> subscribedTopicIds,
207	        Map<String, Integer> memberIndices
208	    ) {
209	        int numMembers = memberIndices.size();
210	        Map<Uuid, List<Integer>> subscribedMembersByTopic = Utils.newHashMap(subscribedTopicIds.size());
211	        groupSpec.memberIds().forEach(memberId -> {
212	            int memberIndex = memberIndices.get(memberId);
213	            MemberSubscription memberSubscription = groupSpec.memberSubscription(memberId);
214	            memberSubscription.subscribedTopicIds().forEach(topicId ->
215	                subscribedMembersByTopic.computeIfAbsent(topicId, k -> new ArrayList<>(numMembers)).add(memberIndex));
216	        });
217	
218	        return subscribedMembersByTopic;
219	    }
220	
221	    /**
222	     * A class that computes the assignment for one topic.
223	     */
224	    private final class TopicAssignmentPartialBuilder {
225	
226	        /**
227	         * The topic ID.
228	         */
229	        private final Uuid topicId;
230	
231	        /**
232	         * The list of assignable topic-partitions for this topic.
233	         */
234	        private final List<TopicIdPartition> targetPartitions;
235	
236	        /**
237	         * The list of member indices subscribed to this topic.
238	         */
239	        private final List<Integer> subscribedMembers;
240	
241	        /**
242	         * The final assignment, grouped by partition index, progressively computed during the assignment building.
243	         */
244	        private final Map<Integer, Set<Integer>> finalAssignmentByPartition;
245	
246	        /**
247	         * The final assignment, grouped by member index, progressively computed during the assignment building.
248	         */
249	        private final Map<Integer, Set<Integer>> finalAssignmentByMember;
250	
251	        /**
252	         * The desired sharing for each target partition.
253	         * For entirely balanced assignment, we would expect (numTargetPartitions / numGroupMembers) partitions per member, rounded upwards.
254	         * That can be expressed as:  Math.ceil(numTargetPartitions / (double) numGroupMembers)
255	         */
256	        private final Integer desiredSharing;
257	
258	        /**
259	         * The desired number of assignments for each share group member.
260	         * <p>
261	         * Members are stored as integer indices into the memberIds array.
262	         */
263	        private final int[] desiredAssignmentCounts;
264	
265	        public TopicAssignmentPartialBuilder(Uuid topicId, int numGroupMembers, List<TopicIdPartition> targetPartitions, List<Integer> subscribedMembers) {
266	            this.topicId = topicId;
267	            this.targetPartitions = targetPartitions;
268	            this.subscribedMembers = subscribedMembers;
269	            this.finalAssignmentByPartition = Utils.newHashMap(targetPartitions.size());
270	            this.finalAssignmentByMember = Utils.newHashMap(subscribedMembers.size());
271	
272	            int numTargetPartitions = targetPartitions.size();
273	            int numSubscribedMembers = subscribedMembers.size();
274	            if (numTargetPartitions == 0) {
275	                this.desiredSharing = 0;
276	            } else {
277	                this.desiredSharing = (numSubscribedMembers + numTargetPartitions - 1) / numTargetPartitions;
278	            }
279	
280	            // Calculate the desired number of assignments for each member.
281	            // The precise desired assignment count per target partition. This can be a fractional number.
282	            // We would expect (numSubscribedMembers / numTargetPartitions) assignments per partition, rounded upwards.
283	            // Using integer arithmetic:  (numSubscribedMembers + numTargetPartitions - 1) / numTargetPartitions
284	            this.desiredAssignmentCounts = new int[numGroupMembers];
285	            double preciseDesiredAssignmentCount = desiredSharing * numTargetPartitions / (double) numSubscribedMembers;
286	            for (int memberIndex = 0; memberIndex < numSubscribedMembers; memberIndex++) {
287	                desiredAssignmentCounts[subscribedMembers.get(memberIndex)] =
288	                    (int) Math.ceil(preciseDesiredAssignmentCount * (double) (memberIndex + 1)) -
289	                        (int) Math.ceil(preciseDesiredAssignmentCount * (double) memberIndex);
290	            }
291	        }
292	
293	        public void build() {
294	            // The order of steps here is not that significant, but assignRemainingPartitions must go last.
295	            revokeUnassignablePartitions();
296	
297	            revokeOverfilledMembers();
298	
299	            revokeOversharedPartitions();
300	
301	            // Add in any partitions which are currently not in the assignment.
302	            targetPartitions.forEach(topicPartition ->
303	                finalAssignmentByPartition.computeIfAbsent(topicPartition.partitionId(), k -> Utils.newHashSet(subscribedMembers.size())));
304	
305	            assignRemainingPartitions();
306	        }
307	
308	        /**
309	         * Examine the members from the current assignment, making sure that no member has too many assigned partitions.
310	         * When looking at the current assignment, we need to only consider the topics in the current assignment that are
311	         * also being subscribed in the new assignment.
312	         */
313	        private void revokeUnassignablePartitions() {
314	            for (Map.Entry<Integer, Map<Uuid, Set<Integer>>> entry : oldGroupAssignment.entrySet()) {
315	                Integer memberIndex = entry.getKey();
316	                Map<Uuid, Set<Integer>> oldMemberAssignment = entry.getValue();
317	                Map<Uuid, Set<Integer>> newMemberAssignment = null;
318	
319	                if (oldMemberAssignment.isEmpty()) {
320	                    continue;
321	                }
322	
323	                Set<Integer> assignedPartitions = oldMemberAssignment.get(topicId);
324	                if (assignedPartitions != null) {
325	                    if (subscribedTopicIds.contains(topicId)) {
326	                        for (int partition : assignedPartitions) {
327	                            finalAssignmentByPartition.computeIfAbsent(partition, k -> new HashSet<>()).add(memberIndex);
328	                            finalAssignmentByMember.computeIfAbsent(memberIndex, k -> new HashSet<>()).add(partition);
329	                        }
330	                    } else {
331	                        // We create a deep copy of the original assignment so we can alter it.
332	                        newMemberAssignment = AssignorHelpers.deepCopyAssignment(oldMemberAssignment);
333	
334	                        // Remove the entire topic.
335	                        newMemberAssignment.remove(topicId);
336	                    }
337	
338	                    if (newMemberAssignment != null) {
339	                        newGroupAssignment.put(memberIndex, newMemberAssignment);
340	                    }
341	                }
342	            }
343	        }
344	
345	        /**
346	         * Revoke partitions from members which are overfilled.
347	         */
348	        private void revokeOverfilledMembers() {
349	            finalAssignmentByMember.forEach((memberIndex, assignedPartitions) -> {
350	                int memberDesiredAssignmentCount = desiredAssignmentCounts[memberIndex];
351	                if (assignedPartitions.size() > memberDesiredAssignmentCount) {
352	                    Map<Uuid, Set<Integer>> newMemberAssignment = newGroupAssignment.get(memberIndex);
353	                    Iterator<Integer> partitionIterator = assignedPartitions.iterator();
354	                    while (partitionIterator.hasNext() && (assignedPartitions.size() > memberDesiredAssignmentCount)) {
355	                        int partitionIndex = partitionIterator.next();
356	                        finalAssignmentByPartition.get(partitionIndex).remove(memberIndex);
357	                        partitionIterator.remove();
358	                        if (newMemberAssignment == null) {
359	                            newMemberAssignment = AssignorHelpers.deepCopyAssignment(oldGroupAssignment.get(memberIndex));
360	                            newGroupAssignment.put(memberIndex, newMemberAssignment);
361	                        }
362	                        newMemberAssignment.get(topicId).remove(partitionIndex);
363	                    }
364	                }
365	            });
366	        }
367	
368	        /**
369	         * Revoke any over-shared partitions.
370	         */
371	        private void revokeOversharedPartitions() {
372	            finalAssignmentByPartition.forEach((partitionIndex, assignedMembers) -> {
373	                int assignedMemberCount = assignedMembers.size();
374	                if (assignedMemberCount > desiredSharing) {
375	                    Iterator<Integer> assignedMemberIterator = assignedMembers.iterator();
376	                    while (assignedMemberIterator.hasNext()) {
377	                        Integer memberIndex = assignedMemberIterator.next();
378	                        Map<Uuid, Set<Integer>> newMemberAssignment = newGroupAssignment.get(memberIndex);
379	                        if (newMemberAssignment == null) {
380	                            newMemberAssignment = AssignorHelpers.deepCopyAssignment(oldGroupAssignment.get(memberIndex));
381	                            newGroupAssignment.put(memberIndex, newMemberAssignment);
382	                        }
383	                        Set<Integer> partitions = newMemberAssignment.get(topicId);
384	                        if (partitions != null) {
385	                            if (partitions.remove(partitionIndex)) {
386	                                assignedMemberCount--;
387	                                assignedMemberIterator.remove();
388	                                finalAssignmentByMember.get(memberIndex).remove(partitionIndex);
389	                            }
390	                        }
391	                        if (assignedMemberCount <= desiredSharing) {
392	                            break;
393	                        }
394	                    }
395	                }
396	            });
397	        }
398	
399	        /**
400	         * Assign partitions to unfilled members. It repeatedly iterates through the unfilled members while running
401	         * once through the set of partitions. When a partition is found that has insufficient sharing, it attempts to assign
402	         * to one of the members.
403	         * <p>
404	         * There is one tricky case here and that's where a partition wants another assignment, but none of the unfilled
405	         * members are able to take it (because they already have that partition). In this situation, we just accept that
406	         * no additional assignments for this partition could be made and carry on. In theory, a different shuffling of the
407	         * partitions would be able to achieve better balance, but it's harmless tolerating a slight imbalance in this case.
408	         * <p>
409	         * Note that finalAssignmentByMember is not maintained by this method which is expected to be the final step in the
410	         * computation.
411	         */
412	        private void assignRemainingPartitions() {
413	            Set<Integer> unfilledMembers = Utils.newHashSet(numGroupMembers);
414	            subscribedMembersByTopic.get(topicId).forEach(memberIndex -> {
415	                Set<Integer> assignedPartitions = finalAssignmentByMember.get(memberIndex);
416	                int numberOfAssignedPartitions = (assignedPartitions == null) ? 0 : assignedPartitions.size();
417	                if (numberOfAssignedPartitions < desiredAssignmentCounts[memberIndex]) {
418	                    unfilledMembers.add(memberIndex);
419	                }
420	            });
421	
422	            Iterator<Integer> memberIterator = unfilledMembers.iterator();
423	            boolean partitionAssignedForThisIterator = false;
424	            for (Map.Entry<Integer, Set<Integer>> partitionAssignment : finalAssignmentByPartition.entrySet()) {
425	                int partitionIndex = partitionAssignment.getKey();
426	                Set<Integer> membersAssigned = partitionAssignment.getValue();
427	
428	                if (membersAssigned.size() < desiredSharing) {
429	                    int assignmentsToMake = desiredSharing - membersAssigned.size();
430	                    while (assignmentsToMake > 0) {
431	                        if (!memberIterator.hasNext()) {
432	                            if (!partitionAssignedForThisIterator) {
433	                                break;
434	                            }
435	                            memberIterator = unfilledMembers.iterator();
436	                            partitionAssignedForThisIterator = false;
437	                        }
438	                        int memberIndex = memberIterator.next();
439	                        if (!membersAssigned.contains(memberIndex)) {
440	                            Map<Uuid, Set<Integer>> newMemberAssignment = newGroupAssignment.get(memberIndex);
441	                            if (newMemberAssignment == null) {
442	                                newMemberAssignment = AssignorHelpers.deepCopyAssignment(oldGroupAssignment.get(memberIndex));
443	                                newGroupAssignment.put(memberIndex, newMemberAssignment);
444	                            }
445	                            newMemberAssignment.computeIfAbsent(topicId, k -> new HashSet<>()).add(partitionIndex);
446	                            finalAssignmentByMember.computeIfAbsent(memberIndex, k -> new HashSet<>()).add(partitionIndex);
447	                            assignmentsToMake--;
448	                            partitionAssignedForThisIterator = true;
449	                            if (finalAssignmentByMember.get(memberIndex).size() >= desiredAssignmentCounts[memberIndex]) {
450	                                memberIterator.remove();
451	                            }
452	                        }
453	                    }
454	                }
455	
456	                if (unfilledMembers.isEmpty()) {
457	                    break;
458	                }
459	            }
460	        }
461	    }
462	}
