18	
19	import org.apache.kafka.common.Uuid;
20	import org.apache.kafka.coordinator.group.Utils;
21	import org.apache.kafka.coordinator.group.api.assignor.GroupAssignment;
22	import org.apache.kafka.coordinator.group.api.assignor.GroupSpec;
23	import org.apache.kafka.coordinator.group.api.assignor.MemberAssignment;
24	import org.apache.kafka.coordinator.group.api.assignor.PartitionAssignorException;
25	import org.apache.kafka.coordinator.group.api.assignor.SubscribedTopicDescriber;
26	import org.apache.kafka.coordinator.group.modern.MemberAssignmentImpl;
27	
28	import java.util.ArrayList;
29	import java.util.Arrays;
30	import java.util.Collection;
31	import java.util.Comparator;
32	import java.util.HashMap;
33	import java.util.HashSet;
34	import java.util.List;
35	import java.util.Map;
36	import java.util.Set;
37	
38	/**
39	 * The heterogeneous uniform assignment builder is used to generate the target assignment for a consumer group with
40	 * at least one of its members subscribed to a different set of topics.
41	 * <p/>
42	 * Assignments are done according to the following principles:
43	 * <ol>
44	 *   <li>Balance:          Ensure partitions are distributed equally among all members.
45	 *                         The difference in assignments sizes between any two members
46	 *                         should not exceed one partition.</li>
47	 *   <li>Stickiness:       Minimize partition movements among members by retaining
48	 *                         as much of the existing assignment as possible.</li>
49	 * </ol>
50	 *
51	 * This assignment builder prioritizes the above properties in the following order:
52	 *      Balance > Stickiness.
53	 */
54	public class UniformHeterogeneousAssignmentBuilder {
55	
56	    /**
57	     * The maximum number of iterations to perform in the final iterative balancing phase.
58	     * <p/>
59	     * When all subscribers to a topic have the same subscriptions, the final balancing phase
60	     * converges in a single iteration and takes another iteration to detect that no further
61	     * balancing is possible. This describes most subscription patterns.
62	     * <p/>
63	     * When subscribers have overlapping, non-identical subscriptions, the final balancing phase can
64	     * take a lot longer to converge. We assume that each iteration roughly halves the imbalance and
65	     * choose a limit that allows for a reasonable balance to be achieved without taking too long.
66	     */
67	    private static final int MAX_ITERATION_COUNT = 16;
68	
69	    /**
70	     * The group metadata specification.
71	     */
72	    private final GroupSpec groupSpec;
73	
74	    /**
75	     * The topic and partition metadata describer.
76	     */
77	    private final SubscribedTopicDescriber subscribedTopicDescriber;
78	
79	    /**
80	     * The list of all the topic Ids that the consumer group is subscribed to.
81	     */
82	    private final Set<Uuid> subscribedTopicIds;
83	
84	    /**
85	     * The list of members in the consumer group.
86	     */
87	    private final List<String> memberIds;
88	
89	    /**
90	     * Maps member ids to their indices in the memberIds list.
91	     */
92	    private final Map<String, Integer> memberIndices;
93	
94	    /**
95	     * List of subscribed members for each topic, in ascending order.
96	     * <p/>
97	     * Members are stored as integer indices into the memberIds array.
98	     */
99	    private final Map<Uuid, List<Integer>> topicSubscribers;
100	
101	    /**
102	     * The new assignment that will be returned.
103	     */
104	    private final Map<String, MemberAssignment> targetAssignment;
105	
106	    /**
107	     * The number of partitions each member is assigned in the new assignment.
108	     * <p/>
109	     * The indices are the same as the memberIds array. memberTargetAssignmentSizes[i] contains the
110	     * number of partitions assigned to memberIds[i].
111	     * <p/>
112	     * We use a plain int[] array here for performance reasons. Looking up the number of partitions
113	     * assigned to a given member is a very common operation. By using a plain int[] array, we can
114	     * avoid:
115	     * <ul>
116	     *   <li>the overhead of boxing and unboxing integers.</li>
117	     *   <li>the cost of HashMap lookups.</li>
118	     *   <li>the cost of checking member ids for equality when there are HashMap collisions.</li>
119	     * </ul>
120	     */
121	    private final int[] memberTargetAssignmentSizes;
122	
123	    /**
124	     * Orders topics by partitions per subscriber, descending.
125	     * <p/>
126	     * Ties are broken by subscriber count, ascending.
127	     * <p/>
128	     * Remaining ties are broken by topic id, ascending.
129	     */
130	    private final Comparator<Uuid> topicComparator;
131	
132	    /**
133	     * Orders members by their number of assigned partitions, ascending.
134	     * <p/>
135	     * Ties are broken by member index, ascending.
136	     */
137	    private final Comparator<Integer> memberComparator;
138	
139	    /**
140	     * Tracks the owner of each partition in the target assignment.
141	     * <p/>
142	     * Owners are represented as indices into the memberIds array.
143	     * -1 indicates an unassigned partition.
144	     */
145	    private final Map<Uuid, int[]> targetAssignmentPartitionOwners;
146	
147	    public UniformHeterogeneousAssignmentBuilder(GroupSpec groupSpec, SubscribedTopicDescriber subscribedTopicDescriber) {
148	        this.groupSpec = groupSpec;
149	        this.subscribedTopicDescriber = subscribedTopicDescriber;
150	        this.subscribedTopicIds = new HashSet<>();
151	
152	        // Number the members 0 to M - 1.
153	        this.memberIds = new ArrayList<>(groupSpec.memberIds());
154	        this.memberIndices = Utils.newHashMap(this.memberIds.size());
155	        for (int memberIndex = 0; memberIndex < this.memberIds.size(); memberIndex++) {
156	            memberIndices.put(memberIds.get(memberIndex), memberIndex);
157	        }
158	
159	        this.topicSubscribers = new HashMap<>();
160	
161	        this.targetAssignment = Utils.newHashMap(this.memberIds.size());
162	        this.memberTargetAssignmentSizes = new int[this.memberIds.size()];
163	
164	        // Build set of all subscribed topics and sets of subscribers per topic.
165	        for (int memberIndex = 0; memberIndex < this.memberIds.size(); memberIndex++) {
166	            String memberId = this.memberIds.get(memberIndex);
167	            for (Uuid topicId : groupSpec.memberSubscription(memberId).subscribedTopicIds()) {
168	                // Check if the subscribed topic exists.
169	                int numPartitions = subscribedTopicDescriber.numPartitions(topicId);
170	                if (numPartitions == -1) {
171	                    throw new PartitionAssignorException(
172	                        "Members are subscribed to topic " + topicId + " which doesn't exist in the topic metadata."
173	                    );
174	                }
175	                subscribedTopicIds.add(topicId);
176	                topicSubscribers.computeIfAbsent(topicId, k -> new ArrayList<>()).add(memberIndex);
177	            }
178	        }
179	
180	        this.topicComparator = (topic1Id, topic2Id) -> {
181	            int topic1PartitionCount = subscribedTopicDescriber.numPartitions(topic1Id);
182	            int topic2PartitionCount = subscribedTopicDescriber.numPartitions(topic2Id);
183	            int topic1SubscriberCount = topicSubscribers.get(topic1Id).size();
184	            int topic2SubscriberCount = topicSubscribers.get(topic2Id).size();
185	
186	            // Order by partitions per subscriber, descending.
187	            int order = Double.compare(
188	                (double) topic2PartitionCount / topic2SubscriberCount,
189	                (double) topic1PartitionCount / topic1SubscriberCount
190	            );
191	
192	            // Then order by subscriber count, ascending.
193	            if (order == 0) {
194	                order = Integer.compare(topic1SubscriberCount, topic2SubscriberCount);
195	            }
196	
197	            // Then order by topic id, ascending.
198	            if (order == 0) {
199	                order = topic1Id.compareTo(topic2Id);
200	            }
201	
202	            return order;
203	        };
204	
205	        this.memberComparator = (memberIndex1, memberIndex2) -> {
206	            // Order by number of assigned partitions, ascending.
207	            int order = Integer.compare(
208	                memberTargetAssignmentSizes[memberIndex1],
209	                memberTargetAssignmentSizes[memberIndex2]
210	            );
211	
212	            // Then order by member index, ascending.
213	            if (order == 0) {
214	                order = memberIndex1.compareTo(memberIndex2);
215	            }
216	
217	            return order;
218	        };
219	
220	        // Initialize partition owners for the target assignments.
221	        this.targetAssignmentPartitionOwners = Utils.newHashMap(this.subscribedTopicIds.size());
222	        for (Uuid topicId : this.subscribedTopicIds) {
223	            int numPartitions = subscribedTopicDescriber.numPartitions(topicId);
224	            int[] partitionOwners = new int[numPartitions];
225	            Arrays.fill(partitionOwners, -1);
226	            this.targetAssignmentPartitionOwners.put(topicId, partitionOwners);
227	        }
228	    }
229	
230	    /**
231	     * Here's the step-by-step breakdown of the assignment process:
232	     * <ol>
233	     *   <li>Revoke partitions from the existing assignment that are no longer part of each member's
234	     *     subscriptions.</li>
235	     *   <li>Allocate all the remaining unassigned partitions to the members in a balanced manner.</li>
236	     *   <li>Iterate through the assignment until it is balanced.</li>
237	     * </ol>
238	     */
239	    public GroupAssignment build() {
240	        if (subscribedTopicIds.isEmpty()) {
241	            return new GroupAssignment(Map.of());
242	        }
243	
244	        maybeRevokePartitions();
245	
246	        Map<Uuid, List<Integer>> unassignedPartitions = computeUnassignedPartitions();
247	        assignRemainingPartitions(unassignedPartitions);
248	
249	        balance();
250	
251	        return new GroupAssignment(targetAssignment);
252	    }
253	
254	    /**
255	     * Sorts topics based on the following criteria:
256	     * <ol>
257	     *   <li>Topics are sorted in descending order of totalPartitions / number of subscribers
258	     *       (partitions per subscriber).</li>
259	     *   <li>Ties are broken by sorting in ascending order of number of subscribers.</li>
260	     *   <li>Any remaining ties are broken by sorting in ascending order of topic id.</li>
261	     * </ol>
262	     *
263	     * The last criteria is for predictability of assignments.
264	     *
265	     * @param topicIds          The topic ids that need to be sorted.
266	     * @return A list of sorted topic ids.
267	     */
268	    private List<Uuid> sortTopicIds(Collection<Uuid> topicIds) {
269	        List<Uuid> sortedTopicIds = new ArrayList<>(topicIds);
270	        sortedTopicIds.sort(topicComparator);
271	        return sortedTopicIds;
272	    }
273	
274	    /**
275	     * Revoke the partitions that are not part of each member's subscriptions.
276	     *
277	     * This method ensures that the original assignment is not copied if it is not altered.
278	     */
279	    private void maybeRevokePartitions() {
280	        for (String memberId : groupSpec.memberIds()) {
281	            int memberIndex = memberIndices.get(memberId);
282	
283	            Map<Uuid, Set<Integer>> oldAssignment = groupSpec.memberAssignment(memberId).partitions();
284	            Map<Uuid, Set<Integer>> newAssignment = null;
285	
286	            // The assignor expects to receive the assignment as an immutable map. It leverages
287	            // this knowledge in order to avoid having to copy all assignments.
288	            if (!AssignorHelpers.isImmutableMap(oldAssignment)) {
289	                throw new IllegalStateException("The assignor expect an immutable map.");
290	            }
291	
292	            for (Map.Entry<Uuid, Set<Integer>> topicPartitions : oldAssignment.entrySet()) {
293	                Uuid topicId = topicPartitions.getKey();
294	                Set<Integer> partitions = topicPartitions.getValue();
295	
296	                if (groupSpec.memberSubscription(memberId).subscribedTopicIds().contains(topicId)) {
297	                    memberTargetAssignmentSizes[memberIndex] += partitions.size();
298	
299	                    for (int partition : partitions) {
300	                        targetAssignmentPartitionOwners.get(topicId)[partition] = memberIndex;
301	                    }
302	                } else {
303	                    if (newAssignment == null) {
304	                        // If the new assignment is null, we create a deep copy of the
305	                        // original assignment so that we can alter it.
306	                        newAssignment = AssignorHelpers.deepCopyAssignment(oldAssignment);
307	                    }
308	                    // Remove the entire topic.
309	                    newAssignment.remove(topicId);
310	                }
311	            }
312	
313	            if (newAssignment == null) {
314	                newAssignment = oldAssignment;
315	            }
316	            targetAssignment.put(memberId, new MemberAssignmentImpl(newAssignment));
317	        }
318	    }
319	
320	    /**
321	     * A class that holds the state for the balancing process.
322	     * <p/>
323	     * Keeps track of two ranges of members: the members with the least number of assigned
324	     * partitions and the members with the most number of assigned partitions. Within each range,
325	     * all members start with the same number of assigned partitions.
326	     */
327	    private final class MemberAssignmentBalancer {
328	        private final int[] memberTargetAssignmentSizes;
329	
330	        /**
331	         * The members to balance, sorted by number of assigned partitions.
332	         * <p/>
333	         * Can be visualized like so:
334	         * <pre>
335	         *           ^
336	         *           |          #
337	         * partition |        ###
338	         * count     |        ###
339	         *           | ##########
340	         *           +----------->
341	         *             members
342	         * </pre>
343	         */
344	        private final List<Integer> sortedMembers;
345	
346	        /**
347	         * [0, leastLoadedRangeEnd) represents the range of members with the smallest partition
348	         * count.
349	         */
350	        private int leastLoadedRangeEnd = 0; // exclusive
351	
352	        /**
353	         * The partition count of each member in the least loaded range before we start assigning
354	         * partitions to them.
355	         */
356	        private int leastLoadedRangePartitionCount = -1;
357	
358	        /**
359	         * The index of the next element in sortedMembers to which to assign the next partition.
360	         */
361	        private int nextLeastLoadedMember = 0;
362	
363	        /**
364	         * [mostLoadedRangeStart, mostLoadedRangeEnd) is the range of members with the largest
365	         * partition count.
366	         */
367	        private int mostLoadedRangeStart = 0; // inclusive
368	
369	        /**
370	         * [mostLoadedRangeStart, mostLoadedRangeEnd) is the range of members with the largest
371	         * partition count.
372	         * <p/>
373	         * mostLoadedRangeEnd is not simply the end of the member list, since we need to be able to
374	         * exclude heavily loaded members which do not have any partitions to give up.
375	         */
376	        private int mostLoadedRangeEnd = 0; // inclusive
377	
378	        /**
379	         * The partition count of each member in the most loaded range before we start unassigning
380	         * partitions from them.
381	         */
382	        private int mostLoadedRangePartitionCount = 1;
383	
384	        /**
385	         * The index of the next element in sortedMembers from which to unassign the next partition.
386	         */
387	        private int nextMostLoadedMember = -1;
388	
389	        // The ranges can be visualized like so:
390	        //
391	        //                         most
392	        //                         loaded
393	        //           ^ least       range
394	        //           | loaded               #
395	        //           | range      [##<-   ]##
396	        // partition |          ##[#######]##
397	        // count     | [...->  ]##[#######]##
398	        //           | [#######]##[#######]##
399	        //           +----------------------->
400	        //             members
401	        //                                 ^^
402	        //                                 These members have no partitions to give up.
403	        //
404	        // The least loaded range expands rightwards and the most loaded range expands leftwards.
405	        // Note that we are not done once the ranges touch, but rather when the partition counts in
406	        // the ranges differ by one or less.
407	
408	        public MemberAssignmentBalancer() {
409	            this.memberTargetAssignmentSizes = UniformHeterogeneousAssignmentBuilder.this.memberTargetAssignmentSizes;
410	            this.sortedMembers = new ArrayList<>(memberTargetAssignmentSizes.length);
411	        }
412	
413	        /**
414	         * Resets the state of the balancer for a new set of members.
415	         *
416	         * @param members The members to balance.
417	         * @return The difference in partition counts between the most and least loaded members.
418	         */
419	        public int initialize(List<Integer> members) {
420	            if (members.isEmpty()) {
421	                // nextLeastLoadedMember needs at least one member.
422	                throw new IllegalArgumentException("Cannot balance an empty subscriber list.");
423	            }
424	
425	            // Build a sorted list of subscribers, where members with the smallest partition count
426	            // appear first.
427	            sortedMembers.clear();
428	            sortedMembers.addAll(members);
429	            sortedMembers.sort(memberComparator);
430	
431	            leastLoadedRangeEnd = 0; // exclusive
432	            leastLoadedRangePartitionCount = memberTargetAssignmentSizes[sortedMembers.get(0)] - 1;
433	            nextLeastLoadedMember = 0;
434	
435	            mostLoadedRangeStart = sortedMembers.size(); // inclusive
436	            mostLoadedRangeEnd = sortedMembers.size(); // exclusive
437	            mostLoadedRangePartitionCount = memberTargetAssignmentSizes[sortedMembers.get(sortedMembers.size() - 1)] + 1;
438	            nextMostLoadedMember = sortedMembers.size() - 1;
439	
440	            return memberTargetAssignmentSizes[sortedMembers.get(sortedMembers.size() - 1)] -
441	                   memberTargetAssignmentSizes[sortedMembers.get(0)];
442	        }
443	
444	        /**
445	         * Gets the least loaded member to which to assign a partition.
446	         * <p/>
447	         * Advances the state of the balancer by assuming that an additional partition has been
448	         * assigned to the returned member.
449	         * <p/>
450	         * Assumes that there is at least one member.
451	         *
452	         * @return The least loaded member to which to assign a partition
453	         */
454	        public int nextLeastLoadedMember() {
455	            // To generate a balanced assignment, we assign partitions to members in the
456	            // [0, leastLoadedRangeEnd) range first. Once each member in the range has received a
457	            // partition, the partition count of the range rises by one and we can try to expand it.
458	            //                                     Range full,             Range full,
459	            //                                     bump level by one       bump level by one,
460	            //                                     can't expand range.     expand range.
461	            //           ^                       ^                       ^
462	            //           |            #          |            #          | [..->     ]#
463	            // partition |          ###    ->    | [..->   ]###    ->    | [.......##]#
464	            // count     | [..->   ]###          | [.......]###          | [.......##]#
465	            //           | [#######]###          | [#######]###          | [#########]#
466	            //           +------------->         +------------->         +------------>
467	            //             members                members                members
468	
469	            if (nextLeastLoadedMember >= leastLoadedRangeEnd) {
470	                // We've hit the end of the range. Bump its level and try to expand it.
471	                leastLoadedRangePartitionCount++;
472	
473	                // Expand the range.
474	                while (leastLoadedRangeEnd < sortedMembers.size() &&
475	                    memberTargetAssignmentSizes[sortedMembers.get(leastLoadedRangeEnd)] == leastLoadedRangePartitionCount) {
476	                    leastLoadedRangeEnd++;
477	                }
478	
479	                // Reset the pointer to the start of the range of members with identical
480	                // partition counts.
481	                nextLeastLoadedMember = 0;
482	            }
483	
484	            int leastLoadedMemberIndex = sortedMembers.get(nextLeastLoadedMember);
485	            nextLeastLoadedMember++;
486	
487	            return leastLoadedMemberIndex;
488	        }
489	
490	        /**
491	         * Gets the most loaded member from which to reassign a partition.
492	         * <p/>
493	         * Advances the state of the balancer by assuming that a partition has been unassigned from
494	         * the returned member.
495	         *
496	         * @return The most loaded member from which to reassign a partition, or -1 if no such
497	         *         member exists.
498	         */
499	        public int nextMostLoadedMember() {
500	            if (nextMostLoadedMember < mostLoadedRangeStart) {
501	                if (mostLoadedRangeEnd <= mostLoadedRangeStart &&
502	                    mostLoadedRangeStart > 0) {
503	                    // The range is empty due to calls to excludeMostLoadedMember(). We risk not
504	                    // expanding the range below and returning a member outside the range. Ensure
505	                    // that we always expand the range below by resetting the partition count.
506	                    mostLoadedRangePartitionCount = memberTargetAssignmentSizes[sortedMembers.get(mostLoadedRangeStart - 1)];
507	                } else {
508	                    mostLoadedRangePartitionCount--;
509	                }
510	
511	                // Expand the range.
512	                while (mostLoadedRangeStart > 0 &&
513	                    memberTargetAssignmentSizes[sortedMembers.get(mostLoadedRangeStart - 1)] == mostLoadedRangePartitionCount) {
514	                    mostLoadedRangeStart--;
515	                }
516	
517	                // Reset the pointer to the end of the range of members with identical partition
518	                // counts.
519	                nextMostLoadedMember = mostLoadedRangeEnd - 1;
520	            }
521	
522	            if (nextMostLoadedMember < 0) {
523	                // The range is empty due to excludeMostLoadedMember() calls and there are no more
524	                // members that can give up partitions.
525	                return -1;
526	            }
527	
528	            int mostLoadedMemberIndex = sortedMembers.get(nextMostLoadedMember);
529	            nextMostLoadedMember--;
530	
531	            return mostLoadedMemberIndex;
532	        }
533	
534	        /**
535	         * Excludes the last member returned from nextMostLoadedMember from the most loaded range.
536	         *
537	         * Must not be called if nextMostLoadedMember has not been called yet or returned -1.
538	         */
539	        public void excludeMostLoadedMember() {
540	            // Kick the member out of the most loaded range by swapping with the member at the end
541	            // of the range and contracting the end of the range.
542	            int mostLoadedMemberIndex = sortedMembers.get(nextMostLoadedMember + 1);
543	            sortedMembers.set(nextMostLoadedMember + 1, sortedMembers.get(mostLoadedRangeEnd - 1));
544	            sortedMembers.set(mostLoadedRangeEnd - 1, mostLoadedMemberIndex);
545	            mostLoadedRangeEnd--;
546	        }
547	
548	        /**
549	         * Checks whether the members are balanced based on the partition counts of the least and
550	         * most loaded ranges.
551	         */
552	        public boolean isBalanced() {
553	            return mostLoadedRangePartitionCount - leastLoadedRangePartitionCount <= 1;
554	        }
555	    }
556	
557	    /**
558	     * Allocates the remaining unassigned partitions to members in a balanced manner.
559	     * <ol>
560	     *   <li>Topics are sorted to maximize the probability of a balanced assignment.</li>
561	     *   <li>Unassigned partitions within each topic are distributed to the least loaded
562	     *       subscribers, repeatedly.</li>
563	     * </ol>
564	     *
565	     * @param partitions        The partitions to be assigned.
566	     */
567	    private void assignRemainingPartitions(Map<Uuid, List<Integer>> partitions) {
568	        List<Uuid> sortedTopicIds = sortTopicIds(partitions.keySet());
569	
570	        MemberAssignmentBalancer memberAssignmentBalancer = new MemberAssignmentBalancer();
571	
572	        for (Uuid topicId : sortedTopicIds) {
573	            memberAssignmentBalancer.initialize(topicSubscribers.get(topicId));
574	
575	            for (int partition : partitions.get(topicId)) {
576	                int leastLoadedMemberIndex = memberAssignmentBalancer.nextLeastLoadedMember();
577	                assignPartition(topicId, partition, leastLoadedMemberIndex);
578	            }
579	        }
580	    }
581	
582	    /**
583	     * If a topic has two or more potential members it is subject to reassignment.
584	     *
585	     * @return true if the topic can participate in reassignment, false otherwise.
586	     */
587	    private boolean canTopicParticipateInReassignment(Uuid topicId) {
588	        return topicSubscribers.get(topicId).size() >= 2;
589	    }
590	
591	    /**
592	     * Balance the current assignment after the initial round of assignments have completed.
593	     */
594	    private void balance() {
595	        Set<Uuid> topicIds = new HashSet<>(subscribedTopicIds);
596	
597	        // Narrow down the reassignment scope to only those topics that can actually be reassigned.
598	        for (Uuid topicId : subscribedTopicIds) {
599	            if (!canTopicParticipateInReassignment(topicId)) {
600	                topicIds.remove(topicId);
601	            }
602	        }
603	
604	        // If all the partitions are fixed i.e. unassigned partitions is empty there is no point of re-balancing.
605	        if (!topicIds.isEmpty()) balanceTopics(topicIds);
606	    }
607	
608	    /**
609	     * Performs reassignments of partitions to balance the load across members.
610	     * This method iteratively reassigns partitions until no further moves can improve the balance.
611	     * <p/>
612	     * The method loops over the topics repeatedly until an entire loop around the topics has
613	     * completed without any reassignments, or we hit an iteration limit.
614	     * <p/>
615	     * This method produces perfectly balanced assignments when all subscribers of a topic have the
616	     * same subscriptions. However, when subscribers have overlapping, non-identical subscriptions,
617	     * the method produces almost-balanced assignments, assuming the iteration limit is not hit.
618	     * eg. if there are three members and two topics and members 1 and 2 are subscribed to the first
619	     *     topic and members 2 and 3 are subscribed to the second topic, we can end up with an
620	     *     assignment like:
621	     * <ul>
622	     *   <li>Member 1: 9 partitions</li>
623	     *   <li>Member 2: 10 partitions</li>
624	     *   <li>Member 3: 11 partitions</li>
625	     * </ul>
626	     *
627	     * In this assignment, the subscribers of the first topic have a difference in partitions of 1,
628	     * so the topic is considered balanced. The same applies to the second topic. However, balance
629	     * can be improved by moving a partition from the second topic from member 3 to member 2 and a
630	     * partition from the first topic from member 2 to member 1.
631	     *
632	     * @param topicIds          The topics to consider for reassignment. These topics must have at
633	     *                          least two subscribers.
634	     */
635	    private void balanceTopics(Collection<Uuid> topicIds) {
636	        List<Uuid> sortedTopicIds = sortTopicIds(topicIds);
637	        // The index of the last topic in sortedTopicIds that was rebalanced.
638	        // Used to decide when to exit early.
639	        int lastRebalanceTopicIndex = -1;
640	
641	        MemberAssignmentBalancer memberAssignmentBalancer = new MemberAssignmentBalancer();
642	
643	        // An array of partitions, with partitions owned by the same member grouped together.
644	        List<Integer> partitions = new ArrayList<>();
645	
646	        // The ranges in the partitions list assigned to members.
647	        // Maintaining these ranges allows for constant time, deterministic picking of partitions
648	        // owned by a given member.
649	        Map<Integer, Integer> startPartitionIndices = new HashMap<>();
650	        Map<Integer, Integer> endPartitionIndices = new HashMap<>(); // exclusive
651	
652	        // Repeat reassignment until no partition can be moved to improve the balance or we hit an
653	        // iteration limit.
654	        for (int i = 0; i < MAX_ITERATION_COUNT; i++) {
655	            for (int topicIndex = 0; topicIndex < sortedTopicIds.size(); topicIndex++) {
656	                if (topicIndex == lastRebalanceTopicIndex) {
657	                    // The last rebalanced topic was this one, which means we've gone through all
658	                    // the topics and didn't perform any additional rebalancing. Don't bother trying
659	                    // to rebalance this topic again and exit.
660	                    return;
661	                }
662	
663	                Uuid topicId = sortedTopicIds.get(topicIndex);
664	
665	                int reassignedPartitionCount = balanceTopic(
666	                    topicId,
667	                    memberAssignmentBalancer,
668	                    partitions,
669	                    startPartitionIndices,
670	                    endPartitionIndices
671	                );
672	
673	                if (reassignedPartitionCount > 0 ||
674	                    lastRebalanceTopicIndex == -1) {
675	                    lastRebalanceTopicIndex = topicIndex;
676	                }
677	            }
678	        }
679	    }
680	
681	    /**
682	     * Performs reassignments of a topic's partitions to balance the load across its subscribers.
683	     *
684	     * @param topicId                  The topic to consider for reassignment. The topic must have
685	     *                                 at least two subscribers.
686	     * @param memberAssignmentBalancer A MemberAssignmentBalancer to hold the state of the balancing
687	     *                                 algorithm.
688	     *                                 subscribers in ascending order of total assigned partitions.
689	     * @param partitions               A list for the balancing algorithm to store the topic's
690	     *                                 partitions, with partitions owned by the same member grouped
691	     *                                 together.
692	     * @param startPartitionIndices    A map for the balancing algorithm to store the ranges in the
693	     *                                 partitions list assigned to members. These ranges allows for
694	     *                                 constant time, deterministic picking of partitions owned by a
695	     *                                 given member.
696	     * @param endPartitionIndices      A map for the balancing algorithm to store the ranges in the
697	     *                                 partitions list assigned to members. These ranges allows for
698	     *                                 constant time, deterministic picking of partitions owned by a
699	     *                                 given member.
700	     * @return the number of partitions reassigned.
701	     */
702	    private int balanceTopic(
703	        Uuid topicId,
704	        MemberAssignmentBalancer memberAssignmentBalancer,
705	        List<Integer> partitions,
706	        Map<Integer, Integer> startPartitionIndices,
707	        Map<Integer, Integer> endPartitionIndices // exclusive
708	    ) {
709	        int reassignedPartitionCount = 0;
710	
711	        int numPartitions = subscribedTopicDescriber.numPartitions(topicId);
712	
713	        int[] partitionOwners = targetAssignmentPartitionOwners.get(topicId);
714	
715	        // Next, try to reassign partitions from the most loaded subscribers to the least loaded
716	        // subscribers. We use a similar approach to assignRemainingPartitions, except instead
717	        // we are reassigning partitions from the most loaded subscribers to the least loaded
718	        // subscribers. Once the difference in partition counts between the ranges is one or less,
719	        // we are done, since reassigning partitions would not improve balance.
720	        int imbalance = memberAssignmentBalancer.initialize(topicSubscribers.get(topicId));
721	        if (imbalance <= 1) {
722	            // The topic is already balanced.
723	            return reassignedPartitionCount;
724	        }
725	
726	        // Initialize the array of partitions, with partitions owned by the same member grouped
727	        // together.
728	        partitions.clear();
729	        for (int partition = 0; partition < numPartitions; partition++) {
730	            partitions.add(partition);
731	        }
732	        partitions.sort(
733	            Comparator
734	                .comparingInt((Integer partition) -> partitionOwners[partition])
735	                .thenComparingInt(partition -> partition)
736	        );
737	
738	        // Initialize the ranges in the partitions list owned by members.
739	        startPartitionIndices.clear();
740	        endPartitionIndices.clear();
741	
742	        for (int i = 0; i < numPartitions; i++) {
743	            int partition = partitions.get(i);
744	            int ownerIndex = partitionOwners[partition];
745	            startPartitionIndices.putIfAbsent(ownerIndex, i);
746	            endPartitionIndices.put(ownerIndex, i + 1); // endPartitionIndices is exclusive
747	        }
748	
749	        // Redistribute partitions from the most loaded subscriber to the least loaded subscriber
750	        // until the topic's subscribers are balanced.
751	        while (!memberAssignmentBalancer.isBalanced()) {
752	            // NB: The condition above does not do much. This loop will terminate due to the checks
753	            //     inside instead.
754	
755	            // First, choose a member from the most loaded range to reassign a partition from.
756	
757	            // Loop until we find a member that has partitions to give up.
758	            int mostLoadedMemberIndex;
759	            while (true) {
760	                mostLoadedMemberIndex = memberAssignmentBalancer.nextMostLoadedMember();
761	
762	                if (mostLoadedMemberIndex == -1) {
763	                    // There are no more members with partitions to give up.
764	                    // We need to break out of two loops here.
765	                    break;
766	                }
767	
768	                if (!endPartitionIndices.containsKey(mostLoadedMemberIndex) ||
